import { Database as Database5 } from "bun:sqlite";
import { join as join10 } from "path";
async function receptionPreflight(options, owner, peerId, participants) {
  const [codex, claude] = participants ?? await Promise.all([
    inspectParticipant(options, owner, "codex"),
    inspectParticipant(options, peerId, "claude")
  ]);
  if (!codex || !claude || codex.sessionId !== owner || claude.sessionId !== peerId)
    throw new Error("Wrong preflight participants");
  const db = new Database5(join10(options.stateDir, owner + ".sqlite"), { readonly: true });
  let policy = "unknown", supported = false;
  try {
    const stored = db.query("SELECT policy FROM inbound_policy WHERE singleton=1").get()?.policy;
    if (["default", "accept", "hold", "refuse"].includes(stored ?? ""))
      policy = stored;
    supported = !!db.query("SELECT 1 FROM receiver_capabilities WHERE capability=? AND pid=? AND proc_start=?").get("project_authorization_v1", codex.pid, codex.procStart);
  } finally {
    db.close();
  }
  const project = codex.project.directory;
  const grant = observeProjectAuthorization(options.stateDir, project);
  const inherited = policy === "default" && supported && grant.enabled && project === claude.project.directory;
  const base = {
    project,
    chatPolicy: policy,
    projectRemembered: grant.enabled,
    receiverSupported: supported,
    effectiveClaudeInbound: "unknown",
    roundTripVerified: false
  };
  const blocked = (code, message) => ({ ...base, readyForCheck: false, code, message });
  if (policy === "hold" || policy === "refuse")
    return blocked("explicit_reception_block", "El chat Codex tiene recepci\xF3n expl\xEDcita " + policy + ", de una versi\xF3n anterior del puente. La autorizaci\xF3n del proyecto no la sustituye: abre un chat nuevo de Codex.");
  if (policy !== "accept" && !inherited)
    return blocked("reception_authorization_required", "Antes de iniciar, confirma \xABRecordar autorizaci\xF3n para este proyecto\xBB en el panel de esta carpeta. Si el receptor es antiguo, rec\xE1rgalo primero. No se enviar\xE1 un nuevo encargo hasta resolverlo.");
  const settings = observeClaudeSettings(options.configDir, claude.project.directory);
  if (settings.some((s) => s.inbound === "hold" || s.inbound === "refuse" || s.messagingDenied.length))
    return blocked("claude_reception_restricted", "Hay una restricci\xF3n observada de recepci\xF3n o mensajer\xEDa en Claude. Rev\xEDsala en la conversaci\xF3n de Claude; el puente no modifica sus permisos.");
  return { ...base, readyForCheck: true, code: "ready_for_round_trip", message: "La recepci\xF3n de Codex permite una comprobaci\xF3n. La recepci\xF3n efectiva de Claude sigue sin observarse: verifica una respuesta correlacionada breve antes de analizar el objetivo. Los ajustes no prueban recepci\xF3n por el modelo." };
}

