// src/claude-server.ts
function claudePaths(env = process.env) {
  return {
    configDir: env.CLAUDE_CONFIG_DIR ?? join19(homedir3(), ".claude"),
    stateDir: env.AGENTS_BRIDGE_STATE_DIR ?? join19(env.CODEX_HOME ?? join19(homedir3(), ".codex"), "plugin-state", stateFolder)
  };
}
function recordObservation(stateDir, entry) {
  appendObservation(stateDir, "observations.jsonl", entry);
}
function metaKeys(meta) {
  return Object.keys(meta ?? {}).sort().slice(0, 64);
}
