    const hostLaunch = {
      pluginRootEnv: options.pluginRootEnv ?? !!process.env.CLAUDE_PLUGIN_ROOT,
      directChildOfEngine: trace[0]?.registered === true,
      launcherOnly: trace.some((step) => step.registered) && between.every((command) => command === "sh" || command === "bun")
    };
